<template>
  <div class="flex flex-col gap-1.5 w-full">
    <p v-if="label" class="text-sm font-medium">{{ label }}</p>
    <Select v-model="value" class="border-border" :disabled="disabled">
      <SelectTrigger class="gap-2" :is-loading="isLoading">
        <SelectValue class="text-foreground-muted" :placeholder="placeholder">
          {{ value ? `${selectedPreLabel ?? ''} ${value.name ?? value.value}` : placeholder }}
        </SelectValue>
      </SelectTrigger>
      <SelectContent>
        <p v-if="!items.length" class="p-4 text-sm text-accent-foreground select-none">No items to select</p>
        <SelectItem v-for="(item, index) in items" v-else :key="index" :value="item" :disabled="item?.disabled">
          {{ item.name ?? item.value }}
        </SelectItem>
      </SelectContent>
    </Select>
    <p v-if="errorMessage && !isOffline" class="p-2 text-sm text-destructive select-none">{{ errorMessage }}</p>
  </div>
</template>

<script setup lang="ts">
import { getErrorMessage } from '~/utils/getErrorMessage';

const { isOffline } = useNetworkStatus();

interface Props {
  label?: string;
  items: SelectItem[];
  placeholder?: string;
  selectedPreLabel?: string;
  isLoading?: boolean;
  error?: string;
  disabled?: boolean;
}

const props = defineProps<Props>();
const errorMessage = computed(() => getErrorMessage(props.error));
const value = defineModel<SelectItem | null>({ default: null });
</script>

<style lang="scss" scoped></style>
